// === Tab: mySketch ===
// idea based on https://openprocessing.org/sketch/492096
var mass = [];
let positions = [];
let velocities = [];

function setup() {
  createCanvas(1112, 834, WEBGL);
  document.oncontextmenu = () => false;   // no right click contextmenu
  noStroke();
	for (let t = 0; t < 30; t++){
    window.simulatedMouseX = random(width);
		window.simulatedMouseY = random(height);
		addNewParticle();
	}
}

function draw() {
  background(32);

  for (var particleA = 0; particleA < mass.length; particleA++) {
    let acc = createVector(0, 0, 0);
    for (var particleB = 0; particleB < mass.length; particleB++) {
      if (particleA != particleB) {
        // with respect to particleA add particleB's jerk to particleA's acceleration
        let diff = p5.Vector.sub(positions[particleB], positions[particleA]);
        let distance = diff.mag();
        if (distance < 1) distance = 1; //rangecheck
        let force_parameter = (distance - 500) * mass[particleB]; // some force parameter
        diff.normalize(); // direction vector
        diff.mult(force_parameter); // map force params onto directions 
        acc.add(diff); // add diff as jerk
      }
    }

    acc.mult(mass[particleA]);
    velocities[particleA].mult(0.99);  //drag
    velocities[particleA].add(acc);
  }

  // draws spheres
  for (var particle = 0; particle < mass.length; particle++) {

    positions[particle].add(velocities[particle]);

    //3d zeugs
    directionalLight(64, 255, 255, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))-width/2, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-height/2,70*(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))*(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))/(windowWidth*windowHeight)+700);
    fill(64, 255, 255);
    specularMaterial(64, 255, 255);
    //ambientMaterial(64, 255, 255);
    //specularColor(64, 255, 255);


    push();
    translate(positions[particle].x-width/2, positions[particle].y-height/2, positions[particle].z-200);
    sphere(mass[particle]*1000, 24, 24);
    pop();
  }

  if (frameCount > 100000) noLoop();
}
///////////////////////////////////////////////////////////////

function addNewParticle() {
  mass.push(random(0.008, 0.04));
  let tempV = createVector(0, 0, 0);
  let tempP = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), random(150));

  velocities.push(tempV);
  positions.push(tempP);
}

function popParticle() {
  let i = random(mass.length);
  mass.splice(i, 1);
  positions.splice(i, 1);
  velocities.splice(i, 1);
}

/////////////////////////////////////////////////////////////////////////////////////////////////////

function keyPressed(){ 
	if (key == 'a'){
    addNewParticle();
  } 
  if (key == 'r'){
    popParticle();
  } 
	if (key == 's'){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
	}
}

